return $input.all().map((item) => {
  const profile = item.json;
  const tasks = [];
  if (profile.bookingLinkStatus !== 'ok') tasks.push(`Fix booking link: ${profile.bookingLinkStatus}`);
  if (profile.availabilityStatus !== 'ok') tasks.push(`Update availability: ${profile.availabilityStatus}`);
  if (profile.phoneStatus !== 'ok') tasks.push(`Review phone number: ${profile.phoneStatus}`);
  if (profile.specialtiesStatus !== 'ok') tasks.push(`Review specialty language: ${profile.specialtiesStatus}`);
  return {
    json: {
      channel: profile.channel,
      url: profile.url,
      lastReviewed: profile.lastReviewed,
      status: tasks.length ? 'needs-action' : 'ok',
      actionCount: tasks.length,
      tasks,
      owner: 'Practice admin demo owner',
      due: 'Next monthly directory review',
      demoOnly: true
    }
  };
});
